import React from "react";

function Dashboard() {
  const user = JSON.parse(localStorage.getItem("user"));

  if (!user) {
    return <p>Please log in first.</p>;
  }

  return (
    <div className="dashboard">
      <h2>Welcome, {user.name}</h2>
      <p>Your role: {user.role}</p>
    </div>
  );
}

export default Dashboard;
